*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --color-bg:           #f5f6fa;
  --color-surface:      #ffffff;
  --color-border:       #d1d5db;
  --color-border-focus: #4f46e5;
  --color-primary:      #4f46e5;
  --color-primary-dark: #3730a3;
  --color-primary-bg:   #eef2ff;
  --color-text:         #111827;
  --color-text-muted:   #6b7280;
  --color-error:        #b91c1c;
  --color-error-bg:     #fef2f2;
  --color-error-border: #fca5a5;
  --color-success:      #065f46;
  --color-success-bg:   #ecfdf5;
  --color-success-border: #6ee7b7;
  --color-check-bg:     #4f46e5;
  --radius-sm:          6px;
  --radius-md:          10px;
  --radius-lg:          16px;
  --shadow-card:        0 1px 3px rgba(0,0,0,.08), 0 4px 16px rgba(0,0,0,.06);
  --font-sans:          system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  --transition:         150ms ease;
}

/* ── Skip link ──────────────────────────────────────────────────────── */
.skip-link {
  position: absolute;
  top: -100%;
  left: 1rem;
  z-index: 9999;
  padding: .5rem 1rem;
  background: var(--color-primary);
  color: #fff;
  font-weight: 600;
  border-radius: 0 0 var(--radius-sm) var(--radius-sm);
  text-decoration: none;
  font-family: var(--font-sans);
  font-size: .875rem;
  transition: top var(--transition);
}
.skip-link:focus { top: 0; }

/* ── Base ───────────────────────────────────────────────────────────── */
body {
  font-family: var(--font-sans);
  background: var(--color-bg);
  color: var(--color-text);
  min-height: 100vh;
  padding: 2rem 1rem 4rem;
  line-height: 1.5;
}

/* ── Page layout ────────────────────────────────────────────────────── */
.page-header {
  text-align: center;
  margin-bottom: 2.5rem;
}
.page-header__eyebrow {
  display: inline-block;
  font-size: .75rem;
  font-weight: 700;
  letter-spacing: .08em;
  text-transform: uppercase;
  color: var(--color-primary);
  background: var(--color-primary-bg);
  padding: .25rem .75rem;
  border-radius: 999px;
  margin-bottom: .75rem;
}
.page-header__title {
  font-size: clamp(1.5rem, 4vw, 2.25rem);
  font-weight: 800;
  color: var(--color-text);
  line-height: 1.2;
}
.page-header__subtitle {
  margin-top: .5rem;
  font-size: 1rem;
  color: var(--color-text-muted);
}

/* ── Quiz card ──────────────────────────────────────────────────────── */
.quiz-card {
  max-width: 660px;
  margin: 0 auto;
  background: var(--color-surface);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-card);
  padding: 2rem 2rem 2.5rem;
}

/* ── Progress bar ───────────────────────────────────────────────────── */
.progress-bar {
  margin-bottom: 2rem;
}
.progress-bar__label {
  display: flex;
  justify-content: space-between;
  font-size: .8125rem;
  font-weight: 500;
  color: var(--color-text-muted);
  margin-bottom: .5rem;
}
.progress-bar__track {
  height: 6px;
  background: var(--color-border);
  border-radius: 999px;
  overflow: hidden;
}
.progress-bar__fill {
  height: 100%;
  background: var(--color-primary);
  border-radius: 999px;
  transition: width .4s ease;
  width: 0%;
}

/* ── Form field (question wrapper) ─────────────────────────────────── */
.form-field {
  margin-bottom: 2rem;
  padding-bottom: 2rem;
  border-bottom: 1px solid var(--color-border);
}
.form-field:last-of-type {
  border-bottom: none;
  margin-bottom: 0;
  padding-bottom: 0;
}

/* ── Fieldset / legend ──────────────────────────────────────────────── */
fieldset {
  border: none;
  padding: 0;
}
.question-legend {
  display: block;
  width: 100%;
}
.question-number {
  display: flex;
  align-items: center;
  gap: .5rem;
  font-size: .8125rem;
  font-weight: 600;
  color: var(--color-primary);
  text-transform: uppercase;
  letter-spacing: .06em;
  margin-bottom: .375rem;
}
.question-number__badge {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 22px;
  height: 22px;
  background: var(--color-primary-bg);
  color: var(--color-primary);
  border-radius: 50%;
  font-size: .75rem;
  font-weight: 700;
  flex-shrink: 0;
}
.question-text {
  font-size: 1.0625rem;
  font-weight: 600;
  color: var(--color-text);
  line-height: 1.4;
  margin-bottom: 0;
}

/* ── Help text ──────────────────────────────────────────────────────── */
.help-text {
  display: flex;
  align-items: flex-start;
  gap: .375rem;
  margin-top: .625rem;
  margin-bottom: .125rem;
  font-size: .875rem;
  color: var(--color-text-muted);
  line-height: 1.4;
}
.help-text__icon {
  flex-shrink: 0;
  margin-top: .1rem;
  width: 16px;
  height: 16px;
  fill: currentColor;
}

/* ── Choices list ───────────────────────────────────────────────────── */
.choices {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: .625rem;
  margin-top: 1rem;
}

.choice {
  position: relative;
}

/* Hide native checkbox visually but keep accessible */
.choice__input {
  position: absolute;
  opacity: 0;
  width: 1px;
  height: 1px;
  margin: 0;
  pointer-events: none;
}

.choice__label {
  display: flex;
  align-items: center;
  gap: .875rem;
  padding: .875rem 1rem;
  border: 1.5px solid var(--color-border);
  border-radius: var(--radius-md);
  cursor: pointer;
  user-select: none;
  transition: border-color var(--transition), background var(--transition), box-shadow var(--transition);
  font-size: .9375rem;
  color: var(--color-text);
}
.choice__label:hover {
  border-color: var(--color-primary);
  background: var(--color-primary-bg);
}

/* Custom checkbox box */
.choice__box {
  flex-shrink: 0;
  width: 20px;
  height: 20px;
  border: 2px solid var(--color-border);
  border-radius: var(--radius-sm);
  background: var(--color-surface);
  display: flex;
  align-items: center;
  justify-content: center;
  transition: border-color var(--transition), background var(--transition);
}
.choice__box-check {
  display: none;
  width: 12px;
  height: 12px;
  fill: #fff;
}

/* Checked state */
.choice__input:checked + .choice__label {
  border-color: var(--color-primary);
  background: var(--color-primary-bg);
}
.choice__input:checked + .choice__label .choice__box {
  background: var(--color-check-bg);
  border-color: var(--color-check-bg);
}
.choice__input:checked + .choice__label .choice__box-check {
  display: block;
}

/* Focus-visible state (keyboard) */
.choice__input:focus-visible + .choice__label {
  outline: 3px solid var(--color-border-focus);
  outline-offset: 2px;
}

/* ── Error messages ─────────────────────────────────────────────────── */
.error-msg {
  display: flex;
  align-items: flex-start;
  gap: .375rem;
  margin-top: .75rem;
  padding: .625rem .75rem;
  background: var(--color-error-bg);
  border: 1px solid var(--color-error-border);
  border-radius: var(--radius-sm);
  color: var(--color-error);
  font-size: .875rem;
  font-weight: 500;
}
.error-msg__icon {
  flex-shrink: 0;
  margin-top: .1rem;
  width: 16px;
  height: 16px;
  fill: currentColor;
}
.error-msg[hidden] { display: none; }

/* Error state on fieldset */
.form-field--error .choice__input:not(:checked) + .choice__label {
  border-color: var(--color-error-border);
}

/* ── Submit area ────────────────────────────────────────────────────── */
.submit-area {
  margin-top: 2rem;
  display: flex;
  align-items: center;
  gap: 1rem;
  flex-wrap: wrap;
}

.btn-submit {
  display: inline-flex;
  align-items: center;
  gap: .5rem;
  padding: .8125rem 1.75rem;
  background: var(--color-primary);
  color: #fff;
  font-size: .9375rem;
  font-weight: 700;
  font-family: var(--font-sans);
  border: none;
  border-radius: var(--radius-md);
  cursor: pointer;
  transition: background var(--transition), transform var(--transition), box-shadow var(--transition);
  box-shadow: 0 1px 3px rgba(79,70,229,.3);
  letter-spacing: .01em;
}
.btn-submit:hover {
  background: var(--color-primary-dark);
  box-shadow: 0 2px 8px rgba(79,70,229,.4);
}
.btn-submit:active { transform: translateY(1px); }
.btn-submit:focus-visible {
  outline: 3px solid var(--color-border-focus);
  outline-offset: 3px;
}
.btn-submit__icon {
  width: 18px;
  height: 18px;
  fill: currentColor;
}

/* ── Status / result banner ─────────────────────────────────────────── */
.status-banner {
  margin-top: 1.5rem;
  padding: 1rem 1.25rem;
  border-radius: var(--radius-md);
  font-size: .9375rem;
  font-weight: 500;
  display: flex;
  align-items: flex-start;
  gap: .625rem;
  border: 1.5px solid transparent;
}
.status-banner[hidden] { display: none; }
.status-banner--success {
  background: var(--color-success-bg);
  border-color: var(--color-success-border);
  color: var(--color-success);
}
.status-banner--error {
  background: var(--color-error-bg);
  border-color: var(--color-error-border);
  color: var(--color-error);
}
.status-banner__icon {
  flex-shrink: 0;
  margin-top: .15rem;
  width: 20px;
  height: 20px;
  fill: currentColor;
}
.status-banner__body { flex: 1; }
.status-banner__title {
  display: block;
  font-weight: 700;
  font-size: 1rem;
  margin-bottom: .25rem;
}
.status-banner__score {
  font-size: 1.5rem;
  font-weight: 800;
}

/* ── Score details ──────────────────────────────────────────────────── */
.score-detail {
  margin-top: 1.5rem;
  display: flex;
  flex-direction: column;
  gap: .75rem;
}
.score-detail[hidden] { display: none; }
.score-detail__item {
  display: flex;
  align-items: center;
  gap: .75rem;
  padding: .75rem 1rem;
  border-radius: var(--radius-md);
  font-size: .875rem;
  font-weight: 500;
  border: 1.5px solid transparent;
}
.score-detail__item--correct {
  background: var(--color-success-bg);
  border-color: var(--color-success-border);
  color: var(--color-success);
}
.score-detail__item--incorrect {
  background: var(--color-error-bg);
  border-color: var(--color-error-border);
  color: var(--color-error);
}
.score-detail__icon {
  flex-shrink: 0;
  width: 18px;
  height: 18px;
  fill: currentColor;
}

/* ── Forced colors (Windows high contrast) ──────────────────────────── */
@media (forced-colors: active) {
  .choice__box { forced-color-adjust: none; border: 2px solid ButtonText; background: Canvas; }
  .choice__input:checked + .choice__label .choice__box { background: Highlight; border-color: Highlight; }
  .btn-submit { forced-color-adjust: none; background: ButtonFace; color: ButtonText; border: 2px solid ButtonText; }
}

/* ── Reduced motion ─────────────────────────────────────────────────── */
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { transition: none !important; animation: none !important; }
}

/* ── Responsive / reflow at 320 px ─────────────────────────────────── */
@media (max-width: 480px) {
  body { padding: 1.25rem .75rem 3rem; }
  .quiz-card { padding: 1.5rem 1.25rem 2rem; }
  .choice__label { padding: .75rem .875rem; font-size: .9rem; }
  .btn-submit { width: 100%; justify-content: center; }
  .submit-area { flex-direction: column; align-items: stretch; }
}
