const QUESTIONS = [
  {
    id: "q1",
    text: "Which of the following are statically typed programming languages?",
    helpText: "A statically typed language checks variable types at compile time, before the program runs.",
    choices: [
      { value: "java",       label: "Java" },
      { value: "python",     label: "Python" },
      { value: "typescript", label: "TypeScript" },
      { value: "cpp",        label: "C++" },
    ],
    correct: new Set(["java", "typescript", "cpp"]),
  },
  {
    id: "q2",
    text: "Which of the following languages were primarily designed for web development?",
    choices: [
      { value: "javascript", label: "JavaScript" },
      { value: "cobol",      label: "COBOL" },
      { value: "php",        label: "PHP" },
      { value: "fortran",    label: "Fortran" },
    ],
    correct: new Set(["javascript", "php"]),
  },
  {
    id: "q3",
    text: "Which of the following are multi-paradigm languages that support object-oriented programming?",
    choices: [
      { value: "haskell", label: "Haskell" },
      { value: "python",  label: "Python" },
      { value: "java",    label: "Java" },
      { value: "prolog",  label: "Prolog" },
    ],
    correct: new Set(["python", "java"]),
  },
];

/* ── Helpers ────────────────────────────────────────────────────────── */
function $(sel, ctx = document) { return ctx.querySelector(sel); }
function $$(sel, ctx = document) { return [...ctx.querySelectorAll(sel)]; }

/* SVG icons (inline, so no extra HTTP requests) */
const ICON_CHECK = `<svg class="choice__box-check" viewBox="0 0 12 12" aria-hidden="true" focusable="false"><path d="M2 6l3 3 5-5"/><path stroke="#fff" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" fill="none" d="M2 6l3 3 5-5"/></svg>`;
const ICON_INFO = `<svg class="help-text__icon" viewBox="0 0 16 16" aria-hidden="true" focusable="false"><circle cx="8" cy="8" r="7" stroke="currentColor" stroke-width="1.5" fill="none"/><path d="M8 7v4M8 5.5v.01" stroke="currentColor" stroke-width="1.5" stroke-linecap="round"/></svg>`;
const ICON_WARNING = `<svg class="error-msg__icon" viewBox="0 0 16 16" aria-hidden="true" focusable="false"><path d="M8 2L14.9 14H1.1L8 2z" stroke="currentColor" stroke-width="1.5" fill="none" stroke-linejoin="round"/><path d="M8 7v3M8 11.5v.01" stroke="currentColor" stroke-width="1.5" stroke-linecap="round"/></svg>`;
const ICON_SUCCESS = `<svg class="status-banner__icon" viewBox="0 0 20 20" aria-hidden="true" focusable="false"><circle cx="10" cy="10" r="9" stroke="currentColor" stroke-width="1.5" fill="none"/><path d="M6 10l3 3 5-5" stroke="currentColor" stroke-width="1.75" stroke-linecap="round" stroke-linejoin="round" fill="none"/></svg>`;
const ICON_FAIL = `<svg class="status-banner__icon" viewBox="0 0 20 20" aria-hidden="true" focusable="false"><circle cx="10" cy="10" r="9" stroke="currentColor" stroke-width="1.5" fill="none"/><path d="M7 7l6 6M13 7l-6 6" stroke="currentColor" stroke-width="1.75" stroke-linecap="round"/></svg>`;
const ICON_ITEM_CORRECT = `<svg class="score-detail__icon" viewBox="0 0 18 18" aria-hidden="true" focusable="false"><circle cx="9" cy="9" r="8" stroke="currentColor" stroke-width="1.5" fill="none"/><path d="M5 9l3 3 5-5" stroke="currentColor" stroke-width="1.75" stroke-linecap="round" stroke-linejoin="round" fill="none"/></svg>`;
const ICON_ITEM_WRONG = `<svg class="score-detail__icon" viewBox="0 0 18 18" aria-hidden="true" focusable="false"><circle cx="9" cy="9" r="8" stroke="currentColor" stroke-width="1.5" fill="none"/><path d="M6 6l6 6M12 6l-6 6" stroke="currentColor" stroke-width="1.75" stroke-linecap="round"/></svg>`;

/* ── Component: render a single question ────────────────────────────── */
function renderQuestion(q, index) {
  const hasHelp = Boolean(q.helpText);
  const helpId = `${q.id}-help`;
  const errorId = `${q.id}-error`;
  const describedBy = [hasHelp ? helpId : null, errorId].filter(Boolean).join(" ");

  const choicesHTML = q.choices.map(c => `
    <li class="choice">
      <input
        class="choice__input"
        type="checkbox"
        id="${q.id}-${c.value}"
        name="${q.id}"
        value="${c.value}"
      >
      <label class="choice__label" for="${q.id}-${c.value}">
        <span class="choice__box" aria-hidden="true">
          ${ICON_CHECK}
        </span>
        ${escapeHTML(c.label)}
      </label>
    </li>
  `).join("");

  const helpHTML = hasHelp
    ? `<p id="${helpId}" class="help-text">${ICON_INFO}${escapeHTML(q.helpText)}</p>`
    : "";

  return `
    <div class="form-field" id="field-${q.id}">
      <fieldset aria-describedby="${describedBy}">
        <legend class="question-legend">
          <span class="question-number">
            <span class="question-number__badge" aria-hidden="true">${index + 1}</span>
            Question ${index + 1} of ${QUESTIONS.length}
          </span>
          <span class="question-text">${escapeHTML(q.text)}</span>
        </legend>
        ${helpHTML}
        <ul class="choices" role="list">
          ${choicesHTML}
        </ul>
        <p id="${errorId}" class="error-msg" hidden aria-live="polite">
          ${ICON_WARNING}
          Error: Select at least one answer to continue.
        </p>
      </fieldset>
    </div>
  `;
}

function escapeHTML(str) {
  return str.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;");
}

/* ── Mount ──────────────────────────────────────────────────────────── */
function mount() {
  const form = document.getElementById("quiz-form");
  const questionsContainer = document.getElementById("quiz-questions");
  const progressFill = document.getElementById("progress-fill");
  const progressText = document.getElementById("progress-text");
  const statusBanner = document.getElementById("status-banner");
  const scoreDetail = document.getElementById("score-detail");

  /* Render questions */
  questionsContainer.innerHTML = QUESTIONS.map((q, i) => renderQuestion(q, i)).join("");

  /* Update progress bar as user answers */
  function updateProgress() {
    const answered = QUESTIONS.filter(q =>
      document.querySelector(`input[name="${q.id}"]:checked`)
    ).length;
    const pct = Math.round((answered / QUESTIONS.length) * 100);
    progressFill.style.width = `${pct}%`;
    progressText.textContent = `${answered} of ${QUESTIONS.length} answered`;
  }

  questionsContainer.addEventListener("change", updateProgress);
  updateProgress();

  /* Validate: returns array of question ids with no selection */
  function validate() {
    return QUESTIONS
      .filter(q => !document.querySelector(`input[name="${q.id}"]:checked`))
      .map(q => q.id);
  }

  /* Show / clear per-question errors */
  function showErrors(invalidIds) {
    QUESTIONS.forEach(q => {
      const field = document.getElementById(`field-${q.id}`);
      const err = document.getElementById(`${q.id}-error`);
      if (invalidIds.includes(q.id)) {
        field.classList.add("form-field--error");
        err.removeAttribute("hidden");
      } else {
        field.classList.remove("form-field--error");
        err.setAttribute("hidden", "");
      }
    });
  }

  /* Score the quiz */
  function score() {
    return QUESTIONS.map(q => {
      const selected = new Set(
        $$(`input[name="${q.id}"]:checked`).map(el => el.value)
      );
      const isCorrect =
        selected.size === q.correct.size &&
        [...selected].every(v => q.correct.has(v));
      return { q, isCorrect, selected };
    });
  }

  /* Render score breakdown */
  function renderScoreDetail(results) {
    scoreDetail.innerHTML = results.map(({ q, isCorrect }) => {
      const correctList = [...q.correct]
        .map(v => q.choices.find(c => c.value === v)?.label ?? v)
        .join(", ");
      const cls = isCorrect ? "score-detail__item--correct" : "score-detail__item--incorrect";
      const icon = isCorrect ? ICON_ITEM_CORRECT : ICON_ITEM_WRONG;
      const label = isCorrect ? "Correct" : `Incorrect — correct: ${escapeHTML(correctList)}`;
      return `
        <div class="score-detail__item ${cls}" role="listitem">
          ${icon}
          <span><strong>Q${QUESTIONS.indexOf(q) + 1}:</strong> ${label}</span>
        </div>
      `;
    }).join("");
    scoreDetail.removeAttribute("hidden");
  }

  /* Submit handler */
  form.addEventListener("submit", e => {
    e.preventDefault();

    const invalidIds = validate();
    if (invalidIds.length) {
      showErrors(invalidIds);
      /* Focus first unanswered question */
      const firstInvalidInput = document.querySelector(
        `input[name="${invalidIds[0]}"]`
      );
      firstInvalidInput?.focus();
      return;
    }

    showErrors([]);

    const results = score();
    const numCorrect = results.filter(r => r.isCorrect).length;
    const total = QUESTIONS.length;
    const allCorrect = numCorrect === total;

    /* Update progress to 100% on submit */
    progressFill.style.width = "100%";
    progressText.textContent = `${total} of ${total} answered`;

    /* Show result banner */
    statusBanner.classList.toggle("status-banner--success", allCorrect);
    statusBanner.classList.toggle("status-banner--error", !allCorrect);
    statusBanner.querySelector(".status-banner__icon-wrap").innerHTML =
      allCorrect ? ICON_SUCCESS : ICON_FAIL;
    statusBanner.querySelector(".status-banner__title").textContent =
      allCorrect ? "Perfect score!" : "Quiz submitted";
    statusBanner.querySelector(".status-banner__score").textContent =
      `${numCorrect} / ${total} correct`;
    statusBanner.removeAttribute("hidden");

    renderScoreDetail(results);

    /* Move focus to the result so screen readers announce it */
    statusBanner.setAttribute("tabindex", "-1");
    statusBanner.focus();
  });
}

