    }).catch(e => window.__axeResult(JSON.stringify({error: e.message})));
  });

  const raw = await resultPromise;
  const violations = JSON.parse(raw);
  console.log(JSON.stringify(violations, null, 2));
  console.log('\nTotal violations:', violations.length || 0);
  await b.close();
})().catch(e => { console.error('ERR:', e.message, e.stack); process.exit(1); });
