  color: var(--color-text-muted);
}

/* ── Quiz card ──────────────────────────────────────────────────────── */
.quiz-card {
  max-width: 660px;
  margin: 0 auto;
  background: var(--color-surface);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-card);
  padding: 2rem 2rem 2.5rem;
}

/* ── Progress bar ───────────────────────────────────────────────────── */
.progress-bar {
  margin-bottom: 2rem;
}
.progress-bar__label {
  display: flex;
