  height: 20px;
  fill: currentColor;
}
.status-banner__body { flex: 1; }
.status-banner__title {
  display: block;
  font-weight: 700;
  font-size: 1rem;
  margin-bottom: .25rem;
}
.status-banner__score {
  font-size: 1.5rem;
  font-weight: 800;
}

/* ── Score details ──────────────────────────────────────────────────── */
.score-detail {
  margin-top: 1.5rem;
