const { chromium } = require('playwright');
const path = require('path');

(async () => {
  const b = await chromium.launch();
  const ctx = await b.newContext();
  const page = await ctx.newPage();
  await page.goto('file://' + path.resolve('index.html'), { waitUntil: 'networkidle' });
  await page.waitForTimeout(500);
  await page.addScriptTag({ path: '/tmp/axe.min.js' });
  await page.waitForTimeout(300);

  let resolve;
  const resultPromise = new Promise(r => { resolve = r; });
  await ctx.exposeFunction('__axeResult', data => resolve(data));

  await page.evaluate(() => {
    window.axe.run().then(r => {
      const all = r.violations.map(v => ({
        id: v.id, impact: v.impact,
        tags: v.tags.filter(t => t.startsWith('wcag') || t === 'best-practice'),
        nodes: v.nodes.map(n => ({ target: n.target, html: n.html.substring(0, 150) }))
      }));
      window.__axeResult(JSON.stringify(all));
    }).catch(e => window.__axeResult(JSON.stringify({error: e.message})));
  });

  const violations = JSON.parse(await resultPromise);
  const wcag = violations.filter(v => !v.tags.includes('best-practice'));
  const bp   = violations.filter(v =>  v.tags.includes('best-practice'));

  console.log('WCAG violations:', wcag.length);
  console.log('Best-practice warnings:', bp.length);
  if (wcag.length) {
    console.log('\nWCAG issues:');
    console.log(JSON.stringify(wcag, null, 2));
  }
  if (bp.length) {
    console.log('\nBP warnings:');
    console.log(JSON.stringify(bp.map(v=>({id:v.id,nodes:v.nodes.map(n=>n.target)})), null, 2));
  }
  await b.close();
  process.exit(wcag.length ? 1 : 0);
})().catch(e => { console.error('ERR:', e.message); process.exit(1); });
